/* FINOVA — a dependency-free, browser-based finance tracker.
   All calculations use integer cents to avoid floating-point rounding issues.
   Every major action is commented to help explain the project at an interview. */
'use strict';
const PROFILE_REGISTRY='finova_profiles_v3';
let profiles=[],activeProfile=null;
// Optional authenticated cloud account; local-only mode remains available.
let cloudUser=null,cloudRevision=0,cloudSaveTimer=null,cloudSaveBusy=false,cloudDirty=false,authPanel=false,authBusy=false;
const isCloud=()=>!!cloudUser&&activeProfile?.id==='cloud-'+cloudUser.id;
const key=(kind)=>`finova_v3_${activeProfile?.id||'none'}_${kind}`;
let STORE='', PREFS='', BUDGET_STORE='';
let goals=[], recurring=[], paletteOpen=false, calendarOffset=0;
const welcome=()=>[{role:'bot',text:`Hi ${prefs.displayName.split(' ')[0]}! I’m Nova, your on-device financial assistant. I can record expenses from messages like “I spent 200 on alcohol”, as well as help with budgets, savings goals and recurring payments.`}];
function saveProfiles(){try{localStorage.setItem(PROFILE_REGISTRY,JSON.stringify({profiles:profiles.filter(p=>!p.id.startsWith('cloud-')),activeId:isCloud()?null:activeProfile?.id||null}));return true;}catch{notify('Could not save profiles in browser storage.');return false;}}
function initProfiles(){try{const registry=JSON.parse(localStorage.getItem(PROFILE_REGISTRY)||'null');profiles=Array.isArray(registry?.profiles)?registry.profiles.filter(p=>typeof p.id==='string'&&typeof p.name==='string').slice(0,30):[];activeProfile=registry?.activeId===null?null:(profiles.find(p=>p.id===registry?.activeId)||profiles[0]||null);}catch{profiles=[];activeProfile=null;}syncProfileKeys();}
function syncProfileKeys(){STORE=key('transactions');PREFS=key('prefs');BUDGET_STORE=key('budgets');}
function saveExtras(){if(isCloud()){scheduleCloudSave();return true;}try{localStorage.setItem(key('goals'),JSON.stringify(goals));localStorage.setItem(key('recurring'),JSON.stringify(recurring));return true;}catch{notify('Unable to save. Browser storage may be full.');return false;}}
function createProfile(name){const firstWorkspace=profiles.length===0;name=name.trim().replace(/\s+/g,' ').slice(0,45);if(!name){notify('Enter a name to create your workspace.');return;}if(profiles.length>=30){notify('Maximum 30 local profiles.');return;}const profile={id:uid(),name};profiles.push(profile);activeProfile=profile;syncProfileKeys();state={transactions:[],demo:false};prefs={displayName:name,theme:'dark'};budgets={};goals=[];recurring=[];
// Move valid, non-sample entries from the earlier single-user FINOVA to the first local workspace.
if(firstWorkspace){try{const old=JSON.parse(localStorage.getItem('finova_data_v1')||'null');if(Array.isArray(old?.transactions))state.transactions=old.transactions.filter(t=>validTransaction(t)&&!t.sample);const oldBudgets=JSON.parse(localStorage.getItem('finova_budgets_v1')||'{}');if(oldBudgets&&typeof oldBudgets==='object')budgets=Object.fromEntries(Object.entries(oldBudgets).filter(([c,v])=>expenseCategories.includes(c)&&Number.isSafeInteger(v)&&v>0));}catch{}}
agentFlow=null;agentMessages=welcome();saveProfiles();save();savePrefs();saveExtras();render();notify(`Welcome to FINOVA, ${name}!${state.transactions.length?' Your previous recorded transactions were carried over.':''}`);}
function chooseProfile(){if(isCloud()){notify('Sign out of your cloud account before switching to a local profile.');return;}activeProfile=null;state={transactions:[],demo:false};prefs={displayName:'You',theme:'dark'};budgets={};goals=[];recurring=[];agentFlow=null;activeModal=null;agentOpen=false;paletteOpen=false;saveProfiles();render();}
function switchProfile(id){if(isCloud()){notify('Sign out before switching local workspaces.');return;}const next=profiles.find(p=>p.id===id);if(!next)return;activeProfile=next;syncProfileKeys();agentFlow=null;load();agentMessages=welcome();saveProfiles();paletteOpen=false;render();notify(`Welcome back, ${prefs.displayName}!`);}
function onboarding(){return `<div class="onboarding-shade"><section class="onboarding-panel"><div class="onboarding-symbol">✦</div><span class="eyebrow">YOUR PERSONAL FINANCE SPACE</span><h1>Money feels better<br><em>when it's yours.</em></h1><p>Create a local workspace with your name. FINOVA remembers your entries on this browser, with separate budgets, goals, and transactions for every local profile.</p><button class="btn btn-outline" type="button" data-action="account">☁ Sign in or create cloud account</button><form id="createProfileForm" class="onboarding-form"><label for="newProfileName">What should we call you?</label><input id="newProfileName" class="field" maxlength="45" required autocomplete="name" placeholder="e.g. Denias" autofocus/><button class="btn btn-primary" type="submit">Create my workspace →</button></form>${profiles.length?`<div class="profile-existing"><div class="muted">Or continue in a saved workspace</div>${profiles.map(p=>`<button type="button" class="profile-choice" data-action="profile-switch" data-id="${esc(p.id)}"><span class="avatar">${esc(p.name.slice(0,1).toUpperCase())}</span>${esc(p.name)} <span>→</span></button>`).join('')}</div>`:''}<small>Local profiles are not password-protected accounts. Anyone using this browser can switch between them. For private cross-device accounts, server-side authentication and a database are required.</small></section></div>`;}

const app = document.getElementById('app');
const expenseCategories = ['Food','Transport','Rent','Utilities','Shopping','Entertainment','Healthcare','Education','Subscriptions','Other Expenses'];
const incomeCategories = ['Salary','Freelance','Business','Investments','Other Income'];
const palette = ['#c4f567','#bb9cff','#7891cc','#f2c78e','#f28a9f','#75c6b3','#c5a1cb','#8a8d99','#f2a67b','#7cc9ec'];
let state = { transactions: [], demo: false };
let prefs = { displayName: 'You', theme: 'dark' };
let page = '/';
let searchText = '', typeFilter = 'all', categoryFilter = 'all', sortBy = 'newest', period = '30', graphMode = 'monthly';
let editingId = null, activeModal = null, toastTimeout;
let agentOpen=false,agentFlow=null,agentMessages=[{role:'bot',text:'Hey! I’m Nova, your finance assistant. Try “I spent 200 on alcohol” to record an expense, or ask for a spending summary.'}];
let budgets={};

const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = cents => 'N$' + (Math.abs(cents) / 100).toLocaleString('en-NA',{minimumFractionDigits:2,maximumFractionDigits:2});
const isoDay = date => `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
const shiftDay = n => { const date = new Date();date.setHours(12,0,0,0);date.setDate(date.getDate()+n);return isoDay(date);};
const prettyDate = iso => new Date(`${iso}T12:00:00`).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'});
const formatYear = date => `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}`;
const uid = () => globalThis.crypto?.randomUUID?.() ?? `${Date.now()}-${Math.random().toString(36).slice(2)}`;
const icon = (text) => `<span aria-hidden="true">${text}</span>`;
function validTransaction(t){return !!t && typeof t.id==='string' && typeof t.description==='string' && Number.isSafeInteger(t.cents) && t.cents>0 && ['income','expense'].includes(t.type) && (t.type==='income'?incomeCategories:expenseCategories).includes(t.category) && /^\d{4}-\d{2}-\d{2}$/.test(t.date) && !Number.isNaN(new Date(`${t.date}T12:00:00`).getTime());}

// Secure account UI is only offered when running through the Node.js server.
function authPanelHtml(){return `<div class="auth-shade" role="presentation"><section class="auth-panel" role="dialog" aria-modal="true" aria-label="FINOVA cloud account"><button type="button" class="auth-close" data-action="auth-close" aria-label="Close">×</button><div class="eyebrow">FINOVA CLOUD</div><h2>${isCloud()?'Your private account':'Your finances, on your devices'}</h2>${isCloud()?`<p>Signed in as ${esc(cloudUser.email)}. Your records are stored in your private server-side workspace.</p><p class="small-note">Keep a JSON backup as well. Sign out on shared devices.</p><button type="button" class="btn btn-outline" data-action="auth-logout">Sign out</button>`:`<p>Create an account or sign in to sync your transactions, budgets and goals. Your existing local workspace is not uploaded automatically.</p><form id="authForm"><label>Name (registration only)<input name="name" autocomplete="name" maxlength="45" placeholder="Your name"></label><label>Email<input name="email" type="email" autocomplete="email" required placeholder="you@example.com"></label><label>Password<input name="password" type="password" autocomplete="current-password" minlength="12" required placeholder="At least 12 characters"></label><div class="auth-actions"><button class="btn btn-primary" name="mode" value="login" type="submit">Sign in</button><button class="btn btn-outline" name="mode" value="register" type="submit">Create account</button></div></form><p id="authError" role="alert" class="small-note"></p>`}</section></div>`;}
function cloudSnapshot(){return {transactions:state.transactions,budgets,goals,recurring,prefs};}
function scheduleCloudSave(){if(!isCloud())return;cloudDirty=true;clearTimeout(cloudSaveTimer);cloudSaveTimer=setTimeout(flushCloudSave,450);}
async function flushCloudSave(){if(!isCloud()||cloudSaveBusy||!cloudDirty)return;cloudSaveBusy=true;cloudDirty=false;const data=JSON.parse(JSON.stringify(cloudSnapshot()));const accountId=cloudUser.id;try{const r=await fetch('/api/account/workspace',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision:cloudRevision,data})});const result=await r.json();if(!r.ok)throw Error(result.error||'Cloud save failed');if(cloudUser?.id===accountId)cloudRevision=result.revision;}catch(err){if(cloudUser?.id===accountId){cloudDirty=true;notify('Cloud sync failed: '+err.message+' Export a backup before closing.');}}finally{cloudSaveBusy=false;if(cloudDirty&&cloudUser?.id===accountId){clearTimeout(cloudSaveTimer);cloudSaveTimer=setTimeout(flushCloudSave,1800);}}}
async function cloudOpenAccount(user){const response=await fetch('/api/account/workspace');if(!response.ok)throw Error('Unable to load account workspace');const snapshot=await response.json();const d=snapshot.data||{};cloudUser=user;cloudRevision=snapshot.revision;activeProfile={id:'cloud-'+user.id,name:user.name};syncProfileKeys();state={transactions:(Array.isArray(d.transactions)?d.transactions:[]).filter(validTransaction),demo:false};budgets=d.budgets&&typeof d.budgets==='object'?d.budgets:{};goals=Array.isArray(d.goals)?d.goals:[];recurring=Array.isArray(d.recurring)?d.recurring:[];prefs={displayName:typeof d.prefs?.displayName==='string'?d.prefs.displayName:user.name,theme:['dark','light','system'].includes(d.prefs?.theme)?d.prefs.theme:'dark'};agentMessages=welcome();authPanel=false;saveProfiles();applyTheme();navigate('/dashboard');render();}
async function accountSubmit(form,mode){if(authBusy)return;authBusy=true;const error=document.getElementById('authError');if(error)error.textContent='';try{const values=Object.fromEntries(new FormData(form));const response=await fetch('/api/account/'+mode,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(values)});const data=await response.json();if(!response.ok)throw Error(data.error||'Sign-in failed');await cloudOpenAccount(data.user);notify('Welcome, '+data.user.name+'! Cloud workspace loaded.');}catch(err){const node=document.getElementById('authError');if(node)node.textContent=err.message;else notify(err.message);}finally{authBusy=false;}}
async function cloudLogout(){if(cloudDirty||cloudSaveBusy){await flushCloudSave();if(cloudDirty){notify('Cloud save has not completed; please export a backup before signing out.');return;}}try{await fetch('/api/account/logout',{method:'POST'});}catch{}cloudUser=null;cloudRevision=0;cloudDirty=false;activeProfile=null;state={transactions:[],demo:false};budgets={};goals=[];recurring=[];prefs={displayName:'You',theme:'dark'};agentMessages=[];authPanel=false;saveProfiles();navigate('/');render();notify('Signed out of your cloud account.');}
async function cloudRestore(){try{const r=await fetch('/api/account/me');if(!r.ok)return;const data=await r.json();if(data.user)await cloudOpenAccount(data.user);}catch(e){console.warn('Cloud session unavailable',e.message);}}

// If local storage is corrupt, fall back to an empty but usable application.
function load(){
 state={transactions:[],demo:false};budgets={};goals=[];recurring=[];prefs={displayName:activeProfile?.name||'You',theme:'dark'};
 try {const raw=localStorage.getItem(STORE);if(raw!==null){const parsed=JSON.parse(raw);if(!parsed||!Array.isArray(parsed.transactions))throw Error('Invalid saved data');state={transactions:parsed.transactions.filter(t=>validTransaction(t)&&!t.sample),demo:false};save();}else{state={transactions:[],demo:false};save();}}catch(err){state={transactions:[],demo:false};console.warn('Saved data could not be loaded',err);notify('Saved data could not be read; starting empty.');}
 try{const raw=JSON.parse(localStorage.getItem(PREFS)||'null');if(raw&&typeof raw==='object'){prefs={displayName:typeof raw.displayName==='string'?raw.displayName.slice(0,45):'You',theme:['dark','light','system'].includes(raw.theme)?raw.theme:'dark'};}}catch(err){console.warn('Preferences could not be loaded',err);}
 try{const raw=JSON.parse(localStorage.getItem(BUDGET_STORE)||'{}');budgets=raw&&typeof raw==='object'&&!Array.isArray(raw)?Object.fromEntries(Object.entries(raw).filter(([k,v])=>expenseCategories.includes(k)&&Number.isSafeInteger(v)&&v>0)):{};}catch{budgets={};}
 try{const raw=JSON.parse(localStorage.getItem(key('goals'))||'[]');goals=Array.isArray(raw)?raw.filter(g=>g&&typeof g.id==='string'&&typeof g.name==='string'&&Number.isSafeInteger(g.target)&&g.target>0&&Number.isSafeInteger(g.saved)&&g.saved>=0):[];}catch{goals=[];}
 try{const raw=JSON.parse(localStorage.getItem(key('recurring'))||'[]');recurring=Array.isArray(raw)?raw.filter(r=>r&&typeof r.id==='string'&&validTransaction({...r,id:r.id})&&['weekly','monthly'].includes(r.frequency)&&validDate(r.nextDate)):[];}catch{recurring=[];}
 applyTheme();
}
function save(){if(isCloud()){scheduleCloudSave();return true;}try{localStorage.setItem(STORE,JSON.stringify(state));return true;}catch(e){notify('Unable to save. Check browser storage permissions.');return false;}}
function savePrefs(){if(isCloud()){scheduleCloudSave();return true;}try{localStorage.setItem(PREFS,JSON.stringify(prefs));return true;}catch(e){notify('Unable to save preferences.');return false;}}
function applyTheme(){document.body.classList.toggle('light',prefs.theme==='light'||prefs.theme==='system'&&matchMedia('(prefers-color-scheme: light)').matches);}
function notify(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>el.classList.remove('show'),3300);}
function navigate(path){location.hash=path;}
function readRoute(){const route=decodeURIComponent(location.hash.slice(1))||'/';page=['/','/features','/about','/dashboard','/dashboard/transactions','/dashboard/analytics','/dashboard/budgets','/dashboard/goals','/dashboard/recurring','/dashboard/calendar','/dashboard/insights','/dashboard/settings'].includes(route)?route:'/';searchText='';typeFilter='all';categoryFilter='all';render();window.scrollTo({top:0,behavior:'instant'});}
const logo = () => `<a class="logo" href="#/" aria-label="FINOVA home"><span class="logo-mark">F</span><span>finova<span class="green">.</span></span></a>`;
function websiteHeader(){return `<header class="site-nav">${logo()}<button class="icon-btn menu-toggle" id="marketingMenu" aria-label="Toggle menu">☰</button><nav class="site-links" id="siteLinks"><a class="${page==='/'?'active':''}" href="#/">Home</a><a class="${page==='/features'?'active':''}" href="#/features">Features</a><a class="${page==='/about'?'active':''}" href="#/about">About</a><button type="button" class="btn btn-outline" data-action="account">☁ Sign in</button><a href="#/dashboard" class="btn btn-primary">Launch Dashboard ↗</a></nav></header>`;}
function websiteFooter(){return `<footer class="site-footer"><div>${logo()}<p style="font-size:12px;margin:10px 0 0">A smarter view of your finances. Built for clarity.</p></div><div><a href="#/">Home</a><a href="#/features">Features</a><a href="#/about">About</a><a href="#/dashboard">Dashboard</a></div></footer>`;}
function preview(){return `<div class="hero-preview" aria-label="FINOVA dashboard preview"><div class="preview-top"><span></span><span></span><span></span></div><div class="preview-body"><div class="preview-rail"><b style="font-size:18px">finova<span style="color:#c4f567">.</span></b><div class="rail-item on">◫ &nbsp; Overview</div><div class="rail-item">↔ &nbsp; Transactions</div><div class="rail-item">◩ &nbsp; Analytics</div><div class="rail-item">⚙ &nbsp; Settings</div></div><div class="preview-main"><div style="font-size:20px;font-weight:800">Your money, at a glance <span style="float:right;font-size:12px;color:#999">Dashboard ↗</span></div><div class="preview-cards"><div class="preview-card"><small>Total balance</small><b>${sum(state.transactions,'income')-sum(state.transactions,'expense')<0?'−':''}${money(sum(state.transactions,'income')-sum(state.transactions,'expense'))}</b><small style="color:#c4f567">↗ Financial overview</small></div><div class="preview-card"><small>Income</small><b>${money(sum(state.transactions,'income'))}</b><small>Your entries</small></div><div class="preview-card"><small>Expenses</small><b>${money(sum(state.transactions,'expense'))}</b><small>Your entries</small></div></div><div class="preview-charts"><div class="preview-chart"><div style="font-weight:700;font-size:12px">Money flow · ${state.transactions.length?"Your data":"No data yet"}</div><div class="preview-bars">${chartData().map(x=>`<span style="height:${state.transactions.length?Math.max(1,(x.inc+x.exp)/Math.max(1,...chartData().map(v=>v.inc+v.exp))*100):2}%"></span>`).join('')}</div></div><div class="preview-chart"><div style="font-weight:700;font-size:12px">Expense breakdown</div><div class="preview-donut" style="background:${state.transactions.some(t=>t.type==='expense')?'conic-gradient(var(--lime),var(--purple))':'var(--line)'}"></div></div></div></div></div></div>`;}
const featureItems=[['✦','Nova finance assistant','Create transactions, budgets, goals and recurring reminders with guided conversational actions.'],['◉','Smart monthly budgets','Create category spending limits, see live progress and get warnings as you approach them.'],['◎','Savings goals','Track progress toward a car, laptop or emergency fund and calculate what remains.'],['▦','Financial calendar','See recorded activity and upcoming recurring payments at a glance.'],['↗','Live financial insights','Explore transaction-powered visualizations, trends and spending breakdowns.'],['♙','Personal local workspaces','Every person on this browser can create a named workspace with separate financial records.']];
function featuresCards(count=6){return `<div class="feature-grid">${featureItems.slice(0,count).map(([symbol,title,desc],i)=>`<article class="feature-card"><div class="feature-icon">${symbol}</div><h3>${title}</h3><p>${desc}</p>${count===6&&i===1?`<div class="feature-illustration">${[43,72,53,88,63,100,79].map(h=>`<i style="height:${h}%"></i>`).join('')}</div>`:''}</article>`).join('')}</div>`;}
function siteHome(){return `${websiteHeader()}<main><section class="hero"><span class="pill"><span class="dot"></span> Your finance, reimagined</span><h1>Your finances.<br><em>Finally in focus.</em></h1><p class="lead">Track your money, understand your spending, and make smarter financial decisions — all in one beautifully simple workspace.</p><div class="hero-actions"><a href="#/dashboard" class="btn btn-primary">Launch your dashboard ↗</a><a href="#/features" class="btn btn-outline">Explore features →</a></div>${preview()}</section><section class="section"><div class="section-head"><div><div class="eyebrow">Why FINOVA</div><h2 class="section-title">Money management that just <span class="gradient-text">makes sense.</span></h2></div><p>Less friction, more financial clarity. Everything important, thoughtfully designed.</p></div>${featuresCards(3)}</section><section class="section" style="padding-top:20px"><div class="eyebrow">How it works</div><h2 class="section-title">Three steps to a clearer picture.</h2><div class="steps"><div class="step"><b>01</b><h3>Open your workspace</h3><p>Open a clean workspace with no made-up transactions.</p></div><div class="step"><b>02</b><h3>Add your activity</h3><p>Record your earnings and spending in seconds with a simple form.</p></div><div class="step"><b>03</b><h3>See the big picture</h3><p>Watch your dashboard and analytics respond to the data you enter.</p></div></div></section><section class="section" style="padding-top:35px"><div class="cta"><div class="eyebrow">Make money feel manageable</div><h2>Better financial clarity<br>starts <span class="green">here.</span></h2><p>Everything you need to see where your money goes.</p><a href="#/dashboard" class="btn btn-primary">Launch FINOVA ↗</a></div></section></main>${websiteFooter()}`;}
function siteFeatures(){return `${websiteHeader()}<main><div class="inner-hero"><div class="eyebrow">Thoughtfully built</div><h1>All the tools.<br><span class="gradient-text">None of the noise.</span></h1><p>Explore the simple, powerful features that turn your transactions into a clearer financial picture.</p><a href="#/dashboard" class="btn btn-primary">Try the dashboard ↗</a></div><section class="section" style="padding-top:20px">${featuresCards()}</section><section class="section" style="padding-top:10px"><div class="cta"><h2>See it for yourself.</h2><p>Start with your own transactions and watch everything come to life.</p><a href="#/dashboard" class="btn btn-primary">Explore FINOVA ↗</a></div></section></main>${websiteFooter()}`;}
function siteAbout(){return `${websiteHeader()}<main><div class="inner-hero"><div class="eyebrow">Our purpose</div><h1>Personal finance.<br><span class="gradient-text">Personally empowering.</span></h1><p>FINOVA makes everyday financial tracking approachable, visual, and easy to understand.</p></div><div class="about-card"><div class="eyebrow">The idea behind FINOVA</div><h2>Clearer money decisions start with clearer information.</h2><p>FINOVA is a personal finance demonstration website created to explore thoughtful design and practical software engineering. It brings together a polished public website and a working dashboard for income, expenses, transactions, and analytics.</p><p>Transactions are kept in your own browser using localStorage. FINOVA is not a bank, doesn't connect to financial institutions, and does not synchronize data across devices. Clearing browser storage may remove your data, so export transactions when needed.</p><div style="display:flex;gap:12px;flex-wrap:wrap;margin-top:27px"><a class="btn btn-primary" href="#/dashboard">Open Dashboard ↗</a><a class="btn btn-outline" href="#/features">View Features →</a></div></div></main>${websiteFooter()}`;}
const sideLinks=[['/dashboard','◫','Overview'],['/dashboard/transactions','↔','Transactions'],['/dashboard/analytics','◩','Analytics'],['/dashboard/budgets','◉','Budgets'],['/dashboard/goals','◎','Savings goals'],['/dashboard/recurring','⟳','Recurring'],['/dashboard/calendar','▦','Calendar'],['/dashboard/insights','✦','Insights'],['/dashboard/settings','⚙','Settings']];
function sidebar(){return `<div id="mobileShade" class="mobile-shade"></div><aside class="sidebar" id="sidebar">${logo()}<div><div class="nav-label">WORKSPACE</div>${sideLinks.map(([route,symbol,label])=>`<a class="side-link ${page===route?'active':''}" href="#${route}"><span class="ico">${symbol}</span>${label}</a>`).join('')}</div><div class="sidebar-bottom"><div class="nav-label">MORE</div><a class="side-link" href="#/">← &nbsp; Back to Website</a><div class="demo-label"><b style="color:var(--lime)">● &nbsp; ${esc(prefs.displayName)}'s workspace</b><br>${isCloud()?'Signed in · stored in your cloud account.':'Local profile: not password protected or synced.'} <button class="mini-link" data-action="${isCloud()?'account':'profiles'}">${isCloud()?'Account settings':'Switch profile'}</button></div></div></aside>`;}
function appFrame(body,title){return `<div class="app-shell">${sidebar()}<main class="app-content"><header class="app-header"><div style="display:flex;align-items:center;gap:12px"><button class="icon-btn menu-toggle" id="sidebarToggle" aria-label="Open navigation">☰</button><h2>${title}</h2></div><div class="app-header-right"><button class="btn btn-outline cloud-account-btn" data-action="account">${isCloud()?"☁ Account":"☁ Sign in"}</button><button class="icon-btn" data-action="command-center" title="Command center Ctrl+K" aria-label="Open command center">⌘</button><button class="icon-btn header-search" id="searchShortcut" title="Search transactions" aria-label="Search transactions">⌕</button><button class="icon-btn" id="quickTheme" title="Toggle light or dark theme" aria-label="Toggle theme">◐</button><button class="profile-header" data-action="profiles" title="Switch workspace"><span class="avatar">${esc((prefs.displayName.trim()[0]||'F').toUpperCase())}</span><span class="profile-header-name">${esc(prefs.displayName.split(' ')[0])} ▾</span></button></div></header>${body}</main>${agentDock()}</div>`;}
function topIntro(title,desc,button=true){return `<div class="page-intro"><div><h1>${title}</h1><p>${desc}</p></div>${button?`<button class="btn btn-primary" data-action="add">+ Add Transaction</button>`:''}</div>`;}
function periodTransactions(){const today=new Date();today.setHours(23,59,59,999);let start=new Date(today);if(period==='year'){start=new Date(today.getFullYear(),0,1);}else{start.setDate(start.getDate()-Number(period)+1);start.setHours(0,0,0,0);}return state.transactions.filter(t=>{const date=new Date(`${t.date}T12:00:00`);return date>=start&&date<=today;});}
function sum(transactions,type){return transactions.reduce((total,t)=>total+(t.type===type?t.cents:0),0);}
function statCard(label,value,foot,ico,colour=''){return `<article class="panel stat-card"><small>${label}</small><span class="stat-icon ${colour}">${ico}</span><strong>${value}</strong><div class="sub">${foot}</div></article>`;}
function stats(transactions){const inc=sum(transactions,'income'),exp=sum(transactions,'expense');return `<div class="stat-grid">${statCard('Total balance',(inc-exp<0?'−':'')+money(inc-exp),'Income minus expenses','◈')}${statCard('Total income',money(inc),'All recorded earnings','↗')}${statCard('Total expenses',money(exp),'All recorded spending','↘','purple')}${statCard('Net savings',(inc-exp<0?'−':'')+money(inc-exp),'Net cash flow','◎')}</div>`;}
function chartData(){const list=state.transactions;const now=new Date();const buckets=[];if(graphMode==='weekly'){for(let i=6;i>=0;i--){const d=new Date(now);d.setDate(d.getDate()-i);buckets.push({key:isoDay(d),label:d.toLocaleDateString('en-GB',{weekday:'short'}),inc:0,exp:0});}}else{for(let i=5;i>=0;i--){const d=new Date(now.getFullYear(),now.getMonth()-i,1);buckets.push({key:formatYear(d),label:d.toLocaleDateString('en-GB',{month:'short'}),inc:0,exp:0});}}list.forEach(t=>{const key=graphMode==='weekly'?t.date:t.date.slice(0,7);const b=buckets.find(v=>v.key===key);if(b)b[t.type==='income'?'inc':'exp']+=t.cents;});return buckets;}
function barsPanel(){const buckets=chartData();const max=Math.max(1,...buckets.flatMap(x=>[x.inc,x.exp]));return `<section class="panel"><div class="panel-head"><div><h3>Money flow</h3><p>Income and expenses over time</p></div><div class="segmented"><button data-chart="weekly" class="${graphMode==='weekly'?'selected':''}">7 days</button><button data-chart="monthly" class="${graphMode==='monthly'?'selected':''}">6 months</button></div></div><div class="chart-legend"><span><i style="background:var(--purple)"></i>Income</span><span><i style="background:var(--lime)"></i>Expenses</span></div><div class="bar-chart" role="img" aria-label="Income and expenses bar chart">${buckets.map(x=>`<div class="bar-col"><span class="hint">${esc(x.label)}: +${money(x.inc)} / -${money(x.exp)}</span><div class="bar income" title="Income: ${money(x.inc)}" style="height:${Math.max(1,x.inc/max*100)}%"></div><div class="bar expense" title="Expenses: ${money(x.exp)}" style="height:${Math.max(1,x.exp/max*100)}%"></div></div>`).join('')}</div><div class="chart-labels">${buckets.map(b=>`<span>${b.label}</span>`).join('')}</div></section>`;}
function trendPanel(list=state.transactions){
 const today=new Date();const buckets=[];
 for(let i=11;i>=0;i--){const d=new Date(today.getFullYear(),today.getMonth()-i,1);buckets.push({key:formatYear(d),label:d.toLocaleDateString('en-GB',{month:'short',year:'2-digit'}),income:0,expense:0});}
 for(const tx of list){const b=buckets.find(x=>x.key===tx.date.slice(0,7));if(b)b[tx.type]+=tx.cents;}
 const max=Math.max(1,...buckets.flatMap(x=>[x.income,x.expense]));
 const points=key=>buckets.map((b,i)=>`${32+i*53},${195-b[key]/max*156}`).join(' ');
 const nodes=buckets.map((b,i)=>`<g class="trend-node"><circle cx="${32+i*53}" cy="${195-b.income/max*156}" r="5" fill="var(--purple)"><title>${esc(b.label)} income ${money(b.income)}</title></circle><circle cx="${32+i*53}" cy="${195-b.expense/max*156}" r="5" fill="var(--lime)"><title>${esc(b.label)} expenses ${money(b.expense)}</title></circle></g>`).join('');
 return `<section class="panel trend-panel"><div class="panel-head"><div><h3>Live cash-flow trends</h3><p>Last 12 months · updates as you record transactions</p></div><span class="live-pill"><i></i> LIVE DATA</span></div><div class="chart-legend"><span><i style="background:var(--purple)"></i>Income</span><span><i style="background:var(--lime)"></i>Expenses</span></div>${list.length?`<div class="trend-scroll"><svg class="trend-svg" viewBox="0 0 650 235" role="img" aria-label="12 month income and expense trend from your transactions" preserveAspectRatio="xMidYMid meet"><defs><linearGradient id="trendGlow" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#bb9cff" stop-opacity=".2"/><stop offset="1" stop-color="#bb9cff" stop-opacity="0"/></linearGradient></defs>${[40,90,140,195].map(y=>`<line x1="25" x2="626" y1="${y}" y2="${y}" stroke="var(--line)" stroke-dasharray="3 6"/>`).join('')}<polygon points="32,195 ${points('income')} 615,195" fill="url(#trendGlow)"/><polyline points="${points('income')}" fill="none" stroke="var(--purple)" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round" class="trend-line"/><polyline points="${points('expense')}" fill="none" stroke="var(--lime)" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round" class="trend-line"/>${nodes}${buckets.map((b,i)=>`<text x="${32+i*53}" y="223" text-anchor="middle" fill="var(--muted)" font-size="10">${esc(b.label.split(' ')[0])}</text>`).join('')}</svg></div>`:`<div class="empty"><b>No chart data yet</b>Add your first transaction to see your real cash-flow trends.</div>`}</section>`;
}
function budgetPanel(){const entries=Object.entries(budgets);const thisMonth=state.transactions.filter(t=>t.type==='expense'&&t.date.slice(0,7)===formatYear(new Date()));return `<section class="panel"><div class="panel-head"><div><h3>Monthly category budgets</h3><p>Track spending against the limits you set</p></div><button class="btn btn-outline btn-sm" data-action="agent-budget">✦ Set with Nova</button></div>${entries.length?entries.map(([category,limit])=>{const spent=thisMonth.filter(t=>t.category===category).reduce((n,t)=>n+t.cents,0);const pct=Math.round(spent/limit*100);return `<div class="budget-row"><div><b>${esc(category)}</b><span>${money(spent)} / ${money(limit)} · ${pct}%</span></div><div class="budget-track"><i style="width:${Math.min(100,pct)}%;background:${pct>100?'var(--danger)':'var(--lime)'}"></i></div></div>`;}).join(''):`<div class="empty"><b>No budgets configured</b>Ask Nova: “Set a food budget” to get started.</div>`}</section>`;}
function categoryData(list){const map=new Map();list.filter(t=>t.type==='expense').forEach(t=>map.set(t.category,(map.get(t.category)||0)+t.cents));return [...map].sort((a,b)=>b[1]-a[1]);}
function donutPanel(list){const breakdown=categoryData(list),total=breakdown.reduce((a,b)=>a+b[1],0);if(!total)return `<section class="panel"><div class="panel-head"><div><h3>Spending breakdown</h3><p>Where your money goes</p></div></div><div class="empty"><b>No expenses yet</b>Add an expense to see the breakdown.</div></section>`;let current=0;const segments=breakdown.map(([,v],i)=>{const start=current;current+=v/total*100;return `${palette[i%palette.length]} ${start}% ${current}%`;});return `<section class="panel"><div class="panel-head"><div><h3>Spending breakdown</h3><p>Expenses by category</p></div></div><div class="donut-wrap"><div class="donut" role="img" aria-label="Expense categories shown in legend" style="background:conic-gradient(${segments.join(',')})"><div class="donut-core"><b>${money(total)}</b><small>Total spent</small></div></div><div class="donut-legend">${breakdown.slice(0,6).map(([category,value],i)=>`<button class="donut-drill" data-action="drill-category" data-category="${esc(category)}" title="View ${esc(category)} transactions"><i style="background:${palette[i%palette.length]}"></i><span>${esc(category)}</span><b>${Math.round(value/total*100)}%</b></button>`).join('')}</div></div></section>`;}
function tableRows(list,actions){if(!list.length)return `<tr><td colspan="${actions?6:5}"><div class="empty"><b>No matching transactions</b>Try changing the filters or add a new transaction.</div></td></tr>`;return list.map(t=>`<tr><td><div class="tx-name">${esc(t.description)}</div><div class="tx-sub">${t.sample?'Sample transaction':'Your transaction'}</div></td><td>${esc(prettyDate(t.date))}</td><td>${esc(t.category)}</td><td><span class="badge ${t.type==='expense'?'exp':''}">${t.type==='income'?'Income':'Expense'}</span></td><td class="${t.type==='income'?'amount-pos':'amount-neg'}">${t.type==='income'?'+':'−'}${money(t.cents)}</td>${actions?`<td><div class="action-buttons"><button data-action="edit" data-id="${esc(t.id)}" title="Edit transaction" aria-label="Edit ${esc(t.description)}">✎</button><button data-action="delete" data-id="${esc(t.id)}" title="Delete transaction" aria-label="Delete ${esc(t.description)}">✕</button></div></td>`:''}</tr>`).join('');}
function txTable(list,actions=true){return `<div class="table-scroller"><table class="data-table"><thead><tr><th>TRANSACTION</th><th>DATE</th><th>CATEGORY</th><th>TYPE</th><th>AMOUNT</th>${actions?'<th>ACTIONS</th>':''}</tr></thead><tbody>${tableRows(list,actions)}</tbody></table></div>`;}
function sortedTransactions(){return [...state.transactions].sort((a,b)=>b.date.localeCompare(a.date));}
function overview(){const recent=sortedTransactions().slice(0,5);return appFrame(`${topIntro(`Good to see you, ${esc(prefs.displayName.split(' ')[0]||'there')} 👋`,'Here’s a clear look at your financial activity.')}${state.demo?'<div class="info-strip"><strong>Demo data loaded.</strong> These sample transactions help you explore FINOVA. You can add your own or clear samples in Settings.</div>':''}${stats(state.transactions)}<div class="chart-grid">${barsPanel()}${donutPanel(state.transactions)}</div>${trendPanel()}${insightStrip()}${budgetPanel()}<section class="panel"><div class="panel-head"><div><h3>Recent activity</h3><p>Your latest money movements</p></div><a class="btn btn-outline btn-sm" href="#/dashboard/transactions">View all →</a></div>${txTable(recent,false)}</section>`,'Overview');}
function filteredTransactions(){let list=state.transactions.filter(t=>t.description.toLowerCase().includes(searchText.toLowerCase())||t.category.toLowerCase().includes(searchText.toLowerCase())||t.notes.toLowerCase().includes(searchText.toLowerCase()));if(typeFilter!=='all')list=list.filter(t=>t.type===typeFilter);if(categoryFilter!=='all')list=list.filter(t=>t.category===categoryFilter);return [...list].sort((a,b)=>sortBy==='oldest'?a.date.localeCompare(b.date):sortBy==='highest'?b.cents-a.cents:sortBy==='lowest'?a.cents-b.cents:b.date.localeCompare(a.date));}
function transactionsPage(){const list=filteredTransactions();return appFrame(`${topIntro('Transactions','Manage every money movement in one place.')}<section class="panel"><div class="panel-head"><div><h3>All transactions <span class="muted" style="font-size:13px">(${list.length})</span></h3><p>Search, filter, edit, and organize your records.</p></div><button class="btn btn-outline btn-sm" data-action="export">↓ Export CSV</button></div><div class="toolbar"><input class="field search-field" id="txSearch" aria-label="Search transactions" placeholder="⌕ Search description or category..." value="${esc(searchText)}"/><select class="select" id="typeFilter" aria-label="Filter transaction type"><option value="all">All types</option><option value="income" ${typeFilter==='income'?'selected':''}>Income</option><option value="expense" ${typeFilter==='expense'?'selected':''}>Expenses</option></select><select class="select" id="categoryFilter" aria-label="Filter category"><option value="all">All categories</option>${[...incomeCategories,...expenseCategories].map(c=>`<option value="${c}" ${categoryFilter===c?'selected':''}>${c}</option>`).join('')}</select><select class="select" id="sortBy" aria-label="Sort transactions"><option value="newest" ${sortBy==='newest'?'selected':''}>Newest first</option><option value="oldest" ${sortBy==='oldest'?'selected':''}>Oldest first</option><option value="highest" ${sortBy==='highest'?'selected':''}>Highest amount</option><option value="lowest" ${sortBy==='lowest'?'selected':''}>Lowest amount</option></select></div>${txTable(list)}</section>`,'Transactions');}
function analyticsPage(){const list=periodTransactions(),inc=sum(list,'income'),exp=sum(list,'expense'),net=inc-exp,rate=inc>0?Math.round(net/inc*100):null,topCat=categoryData(list)[0];return appFrame(`<div class="page-intro"><div><h1>Financial analytics</h1><p>Patterns and insights based on your recorded activity.</p></div><select class="select" id="period" aria-label="Analytics date range"><option value="7" ${period==='7'?'selected':''}>Last 7 days</option><option value="30" ${period==='30'?'selected':''}>Last 30 days</option><option value="90" ${period==='90'?'selected':''}>Last 90 days</option><option value="year" ${period==='year'?'selected':''}>This year</option></select></div><div class="stat-grid">${statCard('Period income',money(inc),'Selected time range','↗')}${statCard('Period expenses',money(exp),'Selected time range','↘')}${statCard('Net cash flow',(net<0?'−':'')+money(net),'Income minus expenses','◈')}${statCard('Savings rate',rate===null?'—':rate+'%',rate===null?'No income in selected period':'Net cash flow ÷ income','◎')}</div><div class="chart-grid">${donutPanel(list)}<section class="panel"><div class="panel-head"><div><h3>Your spending insights</h3><p>What stands out in this period</p></div></div><div style="padding:15px 0;border-bottom:1px solid var(--line)"><div class="muted">Largest expense category</div><h2 style="margin:12px 0 5px">${topCat?esc(topCat[0]):'No expenses yet'}</h2><span class="green">${topCat?money(topCat[1]):'N$0.00'}</span></div><div style="padding:22px 0"><div class="muted">Transactions in this period</div><h2 style="margin:9px 0">${list.length}</h2><div class="muted">${list.filter(t=>t.type==='income').length} income · ${list.filter(t=>t.type==='expense').length} expense</div></div></section></div><section class="panel"><div class="panel-head"><div><h3>Period activity</h3><p>Transactions used for these analytics</p></div></div>${txTable([...list].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,8),false)}</section>${trendPanel(list)}`,'Analytics');}
// Every page uses the active browser profile, never records from another workspace.
function currentMonthExpenses(category){return state.transactions.filter(t=>t.type==='expense'&&t.category===category&&t.date.slice(0,7)===formatYear(new Date())).reduce((a,t)=>a+t.cents,0);}
function progressBar(done,target){const rate=target?Math.round(done/target*100):0;return `<div class="budget-track" role="progressbar" aria-valuenow="${Math.min(100,rate)}" aria-valuemin="0" aria-valuemax="100"><i style="width:${Math.min(100,rate)}%;background:${rate>100?'var(--danger)':rate>=80?'#f2c78e':'var(--lime)'}"></i></div>`;}
function insightStrip(){const spend=sum(state.transactions.filter(t=>t.date.slice(0,7)===formatYear(new Date())),'expense');const alerts=Object.entries(budgets).filter(([cat,lim])=>currentMonthExpenses(cat)>=lim*.8).map(([cat,lim])=>`${cat}: ${Math.round(currentMonthExpenses(cat)/lim*100)}% of budget used`);return `<section class="panel insight-strip"><div class="panel-head"><div><h3>✦ Smart insights</h3><p>Calculated from your real records this month</p></div><a class="btn btn-outline btn-sm" href="#/dashboard/insights">View insights →</a></div><div class="insight-cards"><div><span class="muted">Spent this month</span><strong>${money(spend)}</strong></div><div><span class="muted">Tracked categories</span><strong>${categoryData(state.transactions).length}</strong></div><div><span class="muted">Budget alerts</span><strong>${alerts.length}</strong><small>${esc(alerts[0]||'No near-limit budgets')}</small></div></div></section>`;}
function budgetsPage(){const items=expenseCategories.map(cat=>{const lim=budgets[cat]||0,spent=currentMonthExpenses(cat);return `<article class="panel manage-card"><div class="manage-card-head"><span class="category-icon">◈</span><div><h3>${esc(cat)}</h3><p>Spent ${money(spent)} this month</p></div></div><div class="manage-amount">${lim?money(lim):'Not set'} <small>monthly limit</small></div>${lim?`${progressBar(spent,lim)}<div class="manage-hint">${spent>lim?'Over budget by '+money(spent-lim):money(lim-spent)+' remaining'}</div>`:'<div class="manage-hint">Set a limit to track this category</div>'}<div class="manage-actions"><button class="btn btn-outline btn-sm" data-action="budget-edit" data-category="${esc(cat)}">${lim?'Edit limit':'Set limit'}</button>${lim?`<button class="btn btn-ghost btn-sm" data-action="budget-remove" data-category="${esc(cat)}">Remove</button>`:''}</div></article>`;}).join('');return appFrame(`${topIntro('Smart budgets','Define spending limits and see exactly how much room you have left.',false)}<div class="section-kpi"><span class="live-pill"><i></i> THIS MONTH</span><strong>${Object.keys(budgets).length}</strong> active category budgets</div><div class="management-grid">${items}</div>`,'Budgets');}
function goalsPage(){return appFrame(`${topIntro('Savings goals','Turn your plans into progress you can measure.',false)}<div class="page-actions"><button class="btn btn-primary" data-action="goal-add">+ New savings goal</button><button class="btn btn-outline" data-action="agent-goal">✦ Create with Nova</button></div>${goals.length?`<div class="management-grid">${goals.map(g=>{const rem=Math.max(0,g.target-g.saved),months=g.date?Math.max(1,(new Date(g.date+'T12:00:00')-new Date())/(30.44*86400000)):null;return `<article class="panel manage-card"><div class="manage-card-head"><span class="category-icon">◎</span><div><h3>${esc(g.name)}</h3><p>${g.date?'Target date: '+esc(prettyDate(g.date)):'Flexible target date'}</p></div></div><div class="manage-amount">${money(g.saved)} <small>of ${money(g.target)}</small></div>${progressBar(g.saved,g.target)}<div class="manage-hint">${rem?money(rem)+' to go':'🎉 Goal reached!'}${months&&rem?' · '+money(Math.ceil(rem/months))+'/month needed':''}</div><div class="manage-actions"><button class="btn btn-primary btn-sm" data-action="goal-contribute" data-id="${esc(g.id)}">+ Contribute</button><button class="btn btn-outline btn-sm" data-action="goal-edit" data-id="${esc(g.id)}">Edit</button><button class="btn btn-ghost btn-sm" data-action="goal-remove" data-id="${esc(g.id)}">Delete</button></div></article>`;}).join('')}</div>`:'<div class="panel empty"><b>No goals yet</b>Create a savings goal to track your progress.</div>'}<p class="small-note">Savings contributions are tracked against goals, not automatically deducted from your transaction balance. Record a transaction separately if money moves.</p>`,'Savings goals');}
function recurringPage(){return appFrame(`${topIntro('Recurring payments','Track repeating expenses and income. Review each occurrence before recording it.',false)}<div class="page-actions"><button class="btn btn-primary" data-action="recurring-add">+ New recurring item</button><button class="btn btn-outline" data-action="agent-recurring">✦ Ask Nova</button></div>${recurring.length?`<div class="management-grid">${recurring.slice().sort((a,b)=>a.nextDate.localeCompare(b.nextDate)).map(r=>`<article class="panel manage-card"><div class="manage-card-head"><span class="category-icon">⟳</span><div><h3>${esc(r.description)}</h3><p>${esc(r.category)} · ${esc(r.frequency)}</p></div></div><div class="manage-amount">${money(r.cents)}<small>${r.type} · ${prettyDate(r.nextDate)}</small></div><div class="manage-actions"><button class="btn btn-primary btn-sm" data-action="recurring-record" data-id="${esc(r.id)}">Record & advance</button><button class="btn btn-outline btn-sm" data-action="recurring-edit" data-id="${esc(r.id)}">Edit</button><button class="btn btn-ghost btn-sm" data-action="recurring-remove" data-id="${esc(r.id)}">Delete</button></div></article>`).join('')}</div>`:'<div class="panel empty"><b>No recurring payments</b>Add rent, a salary, or a subscription to track your next payment.</div>'}<p class="small-note">Recurring items are reminders, not automatic bank payments. FINOVA never records an upcoming transaction without your action.</p>`,'Recurring');}
function calendarPage(){const now=new Date(),first=new Date(now.getFullYear(),now.getMonth()+calendarOffset,1),yy=first.getFullYear(),mm=first.getMonth(),last=new Date(yy,mm+1,0).getDate(),start=(first.getDay()+6)%7;const events=state.transactions.map(t=>({date:t.date,text:t.description,cents:t.cents,type:t.type})).concat(recurring.map(r=>({date:r.nextDate,text:'Due: '+r.description,cents:r.cents,type:r.type,upcoming:true})));const cells=Array.from({length:start},()=>'<div class="calendar-blank"></div>').concat(Array.from({length:last},(_,i)=>{const d=`${yy}-${String(mm+1).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`,items=events.filter(e=>e.date===d);return `<button class="calendar-day ${d===shiftDay(0)?'today':''}" data-action="calendar-day" data-date="${d}"><b>${i+1}</b>${items.slice(0,3).map(e=>`<span class="calendar-event ${e.upcoming?'due':e.type}">${esc(e.text)} · ${money(e.cents)}</span>`).join('')}${items.length>3?`<small>+${items.length-3} more</small>`:''}</button>`;}));return appFrame(`${topIntro('Financial calendar','Every transaction and upcoming recurring reminder, by date.',false)}<section class="panel"><div class="panel-head calendar-toolbar"><h3>${first.toLocaleDateString('en-GB',{month:'long',year:'numeric'})}</h3><div class="page-actions"><button class="btn btn-outline btn-sm" data-action="cal-prev" aria-label="Previous month">←</button><button class="btn btn-outline btn-sm" data-action="cal-today">Today</button><button class="btn btn-outline btn-sm" data-action="cal-next" aria-label="Next month">→</button></div></div><div class="calendar-scroll"><div class="calendar-grid">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="calendar-weekday">${d}</div>`).join('')}${cells.join('')}</div></div></section><div class="small-note">Click any date to review entries and create a transaction for that day.</div>`,'Calendar');}
function insightsPage(){const today=new Date(),current=formatYear(today),last=formatYear(new Date(today.getFullYear(),today.getMonth()-1,1));const cur=state.transactions.filter(t=>t.date.startsWith(current)),prev=state.transactions.filter(t=>t.date.startsWith(last)),inc=sum(cur,'income'),exp=sum(cur,'expense'),prevExp=sum(prev,'expense'),cats=categoryData(cur),alerts=Object.entries(budgets).map(([cat,lim])=>({cat,spent:currentMonthExpenses(cat),lim})).filter(x=>x.spent>=x.lim*.8);return appFrame(`${topIntro('Financial insights','Clear insights derived from your financial records—not AI guesses.',false)}<div class="stat-grid">${statCard('Income this month',money(inc),'From recorded activity','↗')}${statCard('Expenses this month',money(exp),'From recorded activity','↘')}${statCard('Monthly net',(inc-exp<0?'−':'')+money(inc-exp),'Income minus expenses','◈')}${statCard('Budget warnings',String(alerts.length),'At 80% or more','!')}</div><div class="management-grid"><section class="panel insight-detail"><h3>✦ Spending trend</h3><div class="big-insight">${prevExp?`${exp>=prevExp?'↑':'↓'} ${Math.abs(Math.round((exp-prevExp)/prevExp*100))}%`:'—'}</div><p>${prevExp?'Compared with last month. '+(exp>prevExp?'Spending increased.':exp<prevExp?'Spending decreased.':'Spending was unchanged.'):'Add transactions in consecutive months to see changes.'}</p></section><section class="panel insight-detail"><h3>◎ Top spending category</h3><div class="big-insight">${esc(cats[0]?.[0]||'—')}</div><p>${cats[0]?money(cats[0][1])+' this month':'No expenses recorded this month.'}</p></section><section class="panel insight-detail"><h3>◈ Savings rate</h3><div class="big-insight">${inc?Math.round((inc-exp)/inc*100)+'%':'—'}</div><p>${inc?'Net cash flow divided by income this month.':'Record income to calculate your savings rate.'}</p></section><section class="panel insight-detail"><h3>⚑ Budget notifications</h3>${alerts.length?alerts.map(a=>`<div class="alert-row">${esc(a.cat)} · ${Math.round(a.spent/a.lim*100)}% used${progressBar(a.spent,a.lim)}</div>`).join(''):'<p>No budgets near their spending limits.</p>'}</section></div>${trendPanel()}`,'Insights');}
function commandPalette(){return `<div class="palette-shade" id="paletteShade"><div class="palette-box" role="dialog" aria-modal="true" aria-label="Command center"><div class="palette-search">⌕ <input id="commandInput" placeholder="Search actions and navigate..." autocomplete="off" aria-label="Search commands"/><kbd>ESC</kbd></div><div class="palette-list" id="commandResults">${commandItems().map(c=>`<button data-action="command" data-command="${esc(c[0])}"><span>${c[2]}</span>${esc(c[1])}<span>↗</span></button>`).join('')}</div><p>Navigate with a click. Press Ctrl/⌘ + K to open this command center.</p></div></div>`;}
function commandItems(){return [['/dashboard','Overview','◫'],['/dashboard/transactions','Transactions','↔'],['/dashboard/analytics','Analytics','◩'],['/dashboard/budgets','Budgets','◉'],['/dashboard/goals','Savings goals','◎'],['/dashboard/recurring','Recurring payments','⟳'],['/dashboard/calendar','Calendar','▦'],['/dashboard/insights','Smart insights','✦'],['/dashboard/settings','Settings','⚙'],['add','Add transaction','+'],['goal-add','Create savings goal','◎'],['recurring-add','Create recurring item','⟳'],['profiles','Switch local profile','♙'],['agent-toggle','Ask Nova','✦']];}
function moneyInput(raw){const text=String(raw).trim().replace(/^(N\$|NAD|\$)\s*/i,'').replace(/,/g,'');return /^\d+(\.\d{1,2})?$/.test(text)&&Number.isSafeInteger(Math.round(Number(text)*100))&&Number(text)>0?Math.round(Number(text)*100):null;}
function nextRecurringDate(date,frequency){const d=new Date(date+'T12:00:00');if(frequency==='weekly')d.setDate(d.getDate()+7);else{const day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+1);const last=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();d.setDate(Math.min(day,last));}return isoDay(d);}
function saveBudgets(){if(isCloud()){scheduleCloudSave();return true;}try{localStorage.setItem(BUDGET_STORE,JSON.stringify(budgets));return true;}catch{notify('Could not store budget.');return false;}}
function manageModal(){if(activeModal==='budget-editor'){const cat=editingId||expenseCategories[0];return `<div class="overlay" id="overlay"><form class="modal" id="budgetForm"><h2>Set monthly budget</h2><p>A personal spending limit for this local workspace.</p><label>Category</label><select class="select" name="category">${expenseCategories.map(c=>`<option ${cat===c?'selected':''}>${c}</option>`).join('')}</select><label>Monthly limit (N$)</label><input class="field" name="amount" type="number" step="0.01" min="0.01" required value="${budgets[cat]?(budgets[cat]/100).toFixed(2):''}"/><div class="form-actions"><button type="button" class="btn btn-outline" data-action="cancel">Cancel</button><button class="btn btn-primary">Save budget</button></div></form></div>`;}
if(activeModal==='goal-editor'||activeModal==='goal-contribute'){const g=goals.find(x=>x.id===editingId);if(activeModal==='goal-contribute')return `<div class="overlay" id="overlay"><form class="modal" id="contributionForm"><h2>Contribute to ${esc(g?.name||'goal')}</h2><label>Amount (N$)</label><input class="field" name="amount" type="number" step="0.01" min="0.01" required/><div class="form-actions"><button type="button" class="btn btn-outline" data-action="cancel">Cancel</button><button class="btn btn-primary">Add contribution</button></div></form></div>`;return `<div class="overlay" id="overlay"><form class="modal" id="goalForm"><h2>${g?'Edit':'Create'} savings goal</h2><div class="form-row"><label>Goal name</label><input class="field" name="name" maxlength="80" required value="${esc(g?.name||'')}" placeholder="e.g. New laptop"/></div><div class="form-row"><label>Target amount (N$)</label><input class="field" type="number" name="target" step="0.01" min="0.01" required value="${g?(g.target/100).toFixed(2):''}"/></div><div class="form-row"><label>Already saved (N$)</label><input class="field" type="number" name="saved" step="0.01" min="0" value="${g?(g.saved/100).toFixed(2):'0.00'}"/></div><div class="form-row"><label>Target date (optional)</label><input class="field" type="date" name="date" value="${esc(g?.date||'')}"/></div><div class="form-actions"><button type="button" class="btn btn-outline" data-action="cancel">Cancel</button><button class="btn btn-primary">Save goal</button></div></form></div>`;}
if(activeModal==='recurring-editor'){const r=recurring.find(x=>x.id===editingId),type=r?.type||'expense';return `<div class="overlay" id="overlay"><form class="modal" id="recurringForm"><h2>${r?'Edit':'Create'} recurring item</h2><div class="form-row"><label>Description</label><input class="field" name="description" required maxlength="100" value="${esc(r?.description||'')}" placeholder="e.g. Monthly rent"/></div><div class="form-grid"><div class="form-row"><label>Amount (N$)</label><input class="field" type="number" min="0.01" step="0.01" name="amount" required value="${r?(r.cents/100).toFixed(2):''}"/></div><div class="form-row"><label>Type</label><select class="select" name="type" id="recType"><option value="expense" ${type==='expense'?'selected':''}>Expense</option><option value="income" ${type==='income'?'selected':''}>Income</option></select></div></div><div class="form-grid"><div class="form-row"><label>Category</label><select class="select" name="category" id="recCategory">${(type==='income'?incomeCategories:expenseCategories).map(c=>`<option ${r?.category===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="form-row"><label>Frequency</label><select class="select" name="frequency"><option value="monthly" ${r?.frequency==='monthly'?'selected':''}>Monthly</option><option value="weekly" ${r?.frequency==='weekly'?'selected':''}>Weekly</option></select></div></div><div class="form-row"><label>Next due date</label><input class="field" name="nextDate" type="date" required value="${esc(r?.nextDate||shiftDay(0))}"/></div><div class="form-actions"><button type="button" class="btn btn-outline" data-action="cancel">Cancel</button><button class="btn btn-primary">Save recurring item</button></div></form></div>`;}
if(activeModal==='record-recurring'){const r=recurring.find(x=>x.id===editingId);return `<div class="overlay" id="overlay"><div class="modal"><h2>Record recurring transaction?</h2><p>Record ${esc(r?.description||'')} · ${money(r?.cents||0)} for ${esc(r?.nextDate||'')}, then advance the reminder by one ${esc(r?.frequency||'period')}?</p><div class="form-actions"><button class="btn btn-outline" data-action="cancel">Cancel</button><button class="btn btn-primary" data-action="confirm-record-recurring">Record & advance</button></div></div></div>`;}
if(activeModal==='calendar-date'){const d=editingId,list=state.transactions.filter(t=>t.date===d),due=recurring.filter(t=>t.nextDate===d);return `<div class="overlay" id="overlay"><div class="modal"><h2>${esc(prettyDate(d))}</h2><p>${list.length} recorded transaction(s), ${due.length} recurring reminder(s)</p>${list.map(t=>`<div class="calendar-modal-entry">${esc(t.description)} · ${money(t.cents)}</div>`).join('')}${due.map(r=>`<div class="calendar-modal-entry">Due: ${esc(r.description)} · ${money(r.cents)}</div>`).join('')}<div class="form-actions"><button class="btn btn-outline" data-action="cancel">Close</button><button class="btn btn-primary" data-action="add">+ Add transaction</button></div></div></div>`;}
return '';}
function handleManagementSubmit(form){const d=new FormData(form),id=form.id,amount=moneyInput(d.get('amount'));if(id==='budgetForm'){if(amount===null){notify('Enter a positive budget amount.');return;}budgets[d.get('category')]=amount;saveBudgets();closeModal();notify('Budget saved.');return;}
if(id==='goalForm'){const target=moneyInput(d.get('target')),rawSaved=String(d.get('saved')),saved=rawSaved==='0'||rawSaved==='0.00'?0:moneyInput(rawSaved),name=String(d.get('name')||'').trim(),date=String(d.get('date')||'');if(!name||target===null||saved===null||date&&!validDate(date)){notify('Check the goal name, amounts and target date.');return;}const goal={id:editingId||uid(),name:name.slice(0,80),target,saved,date};goals=editingId?goals.map(g=>g.id===editingId?goal:g):[...goals,goal];saveExtras();closeModal();notify('Savings goal saved.');return;}
if(id==='contributionForm'){const g=goals.find(x=>x.id===editingId);if(amount===null||!g||!Number.isSafeInteger(g.saved+amount)){notify('Enter a valid contribution amount.');return;}g.saved+=amount;saveExtras();closeModal();notify('Contribution recorded toward goal.');return;}
if(id==='recurringForm'){const type=d.get('type'),category=d.get('category'),nextDate=d.get('nextDate'),frequency=d.get('frequency'),description=String(d.get('description')||'').trim();if(!description||amount===null||!validDate(nextDate)||!['weekly','monthly'].includes(frequency)||!(type==='income'?incomeCategories:expenseCategories).includes(category)){notify('Check the recurring item details.');return;}const r={id:editingId||uid(),type,category,description:description.slice(0,100),cents:amount,date:nextDate,nextDate,frequency,notes:''};recurring=editingId?recurring.map(v=>v.id===editingId?r:v):[...recurring,r];saveExtras();closeModal();notify('Recurring reminder saved.');}}
function settingsPage(){return appFrame(`${topIntro('Settings','Make FINOVA feel like your space.',false)}<div class="settings-grid"><section class="panel"><h3>Profile</h3><p>Your display name is stored only in this browser.</p><div class="setting-row"><label for="displayName">Display name</label><input class="field" id="displayName" maxlength="45" value="${esc(prefs.displayName)}" placeholder="Your name"/></div><button class="btn btn-primary btn-sm" data-action="save-name">Save changes</button><div class="small-note">Local workspaces are separated on this device, but have no login security.</div><button class="btn btn-outline btn-sm" data-action="profiles">Switch / add a profile →</button></section><section class="panel"><h3>Appearance</h3><p>Choose the look that feels right for you.</p><div class="setting-row"><label for="themeSelect">Interface theme</label><select class="select" id="themeSelect"><option value="dark" ${prefs.theme==='dark'?'selected':''}>Dark</option><option value="light" ${prefs.theme==='light'?'selected':''}>Light</option><option value="system" ${prefs.theme==='system'?'selected':''}>System preference</option></select></div></section><section class="panel"><h3>Export your data</h3><p>Download your complete transaction history as a spreadsheet-compatible CSV file.</p><div class="page-actions"><button class="btn btn-outline" data-action="export">↓ Export transactions CSV</button><button class="btn btn-primary" data-action="export-profile">↓ Back up entire workspace</button></div><div class="small-note">The JSON backup includes your transactions, budgets, goals and recurring reminders. Save it somewhere safe. CSV contains transactions only.</div></section><section class="panel danger-panel"><h3>Data management</h3><p>Import your transactions from CSV, or permanently clear your records.</p><div style="display:flex;gap:10px;flex-wrap:wrap"><button class="btn btn-outline btn-sm" data-action="import">↑ Import CSV</button><button class="btn btn-outline btn-sm" data-action="import-profile">↑ Restore full backup</button><input id="profileImport" type="file" accept=".json,application/json" hidden><input id="csvImport" type="file" accept=".csv,text/csv" hidden><button class="btn btn-danger btn-sm" data-action="reset">Reset all transactions</button></div><div class="small-note">These operations cannot be undone. Export your data first.</div></section></div>`,'Settings');}
function modalHtml(){if(['budget-editor','goal-editor','goal-contribute','recurring-editor','record-recurring','calendar-date'].includes(activeModal))return manageModal();if(activeModal==='delete'||activeModal==='reset'||activeModal==='clear-demo'){const isDelete=activeModal==='delete',isReset=activeModal==='reset';return `<div class="overlay" id="overlay"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><h2 id="modalTitle">${isDelete?'Delete transaction?':isReset?'Reset all transactions?':'Clear demo transactions?'}</h2><p>${isDelete?'This transaction will be permanently removed.':isReset?'All transactions, budgets, goals and recurring reminders for this local profile will be removed.':'Only the initial sample transactions will be removed. Your own transactions will remain.'}</p><div class="form-actions"><button class="btn btn-outline" data-action="cancel">Cancel</button><button class="btn btn-danger" data-action="confirm-${activeModal}">${isDelete?'Delete':isReset?'Reset all':'Clear samples'}</button></div></div></div>`;}
 const tx=editingId?state.transactions.find(t=>t.id===editingId):null;const type=tx?.type||'expense';const categories=type==='income'?incomeCategories:expenseCategories;return `<div class="overlay" id="overlay"><form class="modal" id="transactionForm" role="dialog" aria-modal="true" aria-labelledby="modalTitle" novalidate><h2 id="modalTitle">${tx?'Edit transaction':'Add transaction'}</h2><p>${tx?'Update the details below.':'Record a new income or expense.'}</p><div class="form-row"><label for="description">Description *</label><input class="field" id="description" name="description" maxlength="100" required value="${esc(tx?.description||'')}" placeholder="e.g. Grocery shopping"/><small id="error-description"></small></div><div class="form-grid"><div class="form-row"><label for="amount">Amount (N$) *</label><input class="field" id="amount" name="amount" type="number" step="0.01" min="0.01" inputmode="decimal" value="${tx?(tx.cents/100).toFixed(2):''}" placeholder="0.00" required/><small id="error-amount"></small></div><div class="form-row"><label for="txType">Type *</label><select class="select" id="txType" name="type"><option value="expense" ${type==='expense'?'selected':''}>Expense</option><option value="income" ${type==='income'?'selected':''}>Income</option></select></div></div><div class="form-grid"><div class="form-row"><label for="txCategory">Category *</label><select class="select" id="txCategory" name="category">${categories.map(c=>`<option value="${c}" ${tx?.category===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="form-row"><label for="txDate">Date *</label><input class="field" id="txDate" name="date" type="date" value="${tx?.date||shiftDay(0)}" required/><small id="error-date"></small></div></div><div class="form-row"><label for="txNotes">Notes (optional)</label><textarea class="field" name="notes" id="txNotes" rows="2" maxlength="300" placeholder="Anything else to remember...">${esc(tx?.notes||'')}</textarea></div><div class="form-actions"><button class="btn btn-outline" data-action="cancel" type="button">Cancel</button><button class="btn btn-primary" type="submit">${tx?'Save changes':'Add transaction'} →</button></div></form></div>`;}
// Nova is a private, guided assistant that works locally in the browser.
function agentDock(){
 return `<div class="nova-root ${agentOpen?'nova-expanded':''}"><button class="nova-fab" data-action="agent-toggle" aria-expanded="${agentOpen}" aria-controls="novaPanel"><span>✦</span> ${agentOpen?'Close Nova':'Ask Nova'} <i class="nova-pulse"></i></button>${agentOpen?`<section class="nova-panel" id="novaPanel" aria-label="Nova finance assistant"><div class="nova-head"><div class="nova-avatar">✦</div><div><strong>Nova <span class="nova-status">● On-device</span></strong><small>Guided finance assistant · no cloud AI</small></div><button class="nova-close" aria-label="Close Nova" data-action="agent-toggle">×</button></div>
 <div class="nova-chat" id="novaChat" aria-live="polite">${agentMessages.map(m=>`<div class="nova-message ${m.role}">${esc(m.text).replace(/\n/g,'<br>')}</div>`).join('')}</div>
 ${agentFlow?.step==='confirm'?`<div class="nova-confirm"><button class="btn btn-primary btn-sm" data-action="agent-confirm">Confirm action ✓</button><button class="btn btn-outline btn-sm" data-action="agent-cancel">Cancel</button></div>`:`<div class="nova-chips">${['Add expense','Add income','Spending summary','Set a budget','Create savings goal','Recurring payment'].map(c=>`<button data-agent-prompt="${c}">${c}</button>`).join('')}</div>`}
 <form id="novaForm" class="nova-composer"><input id="novaInput" autocomplete="off" maxlength="1200" placeholder="Try “add an expense” or “show my spending summary”" aria-label="Message Nova"/><button type="submit" aria-label="Send message">➤</button></form><div class="nova-disclaimer">Nova uses guided prompts locally and does not send your financial records to an AI service.</div></section>`:''}</div>`;
}
function agentSay(text){agentMessages.push({role:'bot',text});if(agentMessages.length>28)agentMessages=agentMessages.slice(-28);render();const box=document.getElementById('novaChat');if(box)box.scrollTop=box.scrollHeight;}
function agentReply(text){agentMessages.push({role:'user',text});if(agentMessages.length>28)agentMessages=agentMessages.slice(-28);}
function agentCancel(){agentFlow=null;agentSay('Cancelled. Nothing was changed. What else can I help you with?');}
function validDate(text){return /^\d{4}-\d{2}-\d{2}$/.test(text)&&!Number.isNaN(Date.parse(text+'T12:00:00'))&&isoDay(new Date(text+'T12:00:00'))===text;}
function beginTransaction(type){agentFlow={kind:'transaction',step:'description',values:{type}};agentSay(`Let's create an ${type} transaction. What is the transaction name or description?`);}
function beginBudget(){agentFlow={kind:'budget',step:'category',values:{}};agentSay(`Which expense category needs a monthly budget? Choose one: ${expenseCategories.join(', ')}.`);}
function agentSummary(){const inc=sum(state.transactions,'income'),exp=sum(state.transactions,'expense'),top=categoryData(state.transactions)[0];agentSay(`Your recorded finances:\n• Income: ${money(inc)}\n• Expenses: ${money(exp)}\n• Net balance: ${inc-exp<0?'-':''}${money(inc-exp)}\n• Transactions: ${state.transactions.length}${top?`\n• Largest spending category: ${top[0]} (${money(top[1])})`:''}\nThese figures update whenever you add, edit, or remove records.`);}
function agentHandleFlow(value){const f=agentFlow;if(!f)return;const v=value.trim();if(/^(cancel|stop|nevermind)$/i.test(v)){agentCancel();return;}
 if(f.kind==='goal'||f.kind==='recurring'){agentExtendedFlow(v);return;}
 if(f.kind==='transaction'){
  if(f.step==='description'){if(!v||v.length>100){agentSay('Please enter a description between 1 and 100 characters.');return;}f.values.description=v;f.step='amount';agentSay(`How much was “${v}” in Namibian dollars? (e.g. 250.00)`);return;}
  if(f.step==='amount'){const raw=v.replace(/^(N\$|NAD|\$)\s*/i,'').replace(/,/g,'');if(!/^\d+(\.\d{1,2})?$/.test(raw)||!Number.isSafeInteger(Math.round(Number(raw)*100))||Number(raw)<=0){agentSay('Please enter a positive amount, such as 125 or 125.50.');return;}f.values.cents=Math.round(Number(raw)*100);f.step='category';agentSay(`Which ${f.values.type} category?\n${(f.values.type==='income'?incomeCategories:expenseCategories).join(' · ')}`);return;}
  if(f.step==='category'){const opts=f.values.type==='income'?incomeCategories:expenseCategories;const cat=opts.find(c=>c.toLowerCase()===v.toLowerCase());if(!cat){agentSay(`Choose a category from: ${opts.join(', ')}.`);return;}f.values.category=cat;f.step='date';agentSay('What was the date? Enter YYYY-MM-DD, or say “today” or “yesterday”.');return;}
  if(f.step==='date'){const date=/^today$/i.test(v)?shiftDay(0):/^yesterday$/i.test(v)?shiftDay(-1):v;if(!validDate(date)){agentSay('That date is not valid. Enter YYYY-MM-DD or “today”.');return;}f.values.date=date;f.step='notes';agentSay('Any optional notes? Type your notes, or “skip”.');return;}
  if(f.step==='notes'){f.values.notes=/^(skip|none|no)$/i.test(v)?'':v.slice(0,300);f.step='confirm';agentSay(`Review before saving:\n${f.values.type.toUpperCase()} · ${f.values.description}\nAmount: ${money(f.values.cents)}\nCategory: ${f.values.category}\nDate: ${f.values.date}\nNotes: ${f.values.notes||'None'}\nSelect “Confirm action” to save.`);return;}
  if(f.step==='confirm'){agentSay('Use “Confirm action” or “Cancel” below to finish safely.');return;}
 }
 if(f.kind==='budget'){
  if(f.step==='category'){const cat=expenseCategories.find(c=>c.toLowerCase()===v.toLowerCase());if(!cat){agentSay(`Please pick one of: ${expenseCategories.join(', ')}.`);return;}f.values.category=cat;f.step='amount';agentSay(`What monthly limit would you like for ${cat}? Enter an amount in N$.`);return;}
  if(f.step==='amount'){const raw=v.replace(/^(N\$|NAD|\$)\s*/i,'').replace(/,/g,'');if(!/^\d+(\.\d{1,2})?$/.test(raw)||!Number.isSafeInteger(Math.round(Number(raw)*100))||Number(raw)<=0){agentSay('Enter a positive amount like 1500 or 1500.50.');return;}f.values.cents=Math.round(Number(raw)*100);f.step='confirm';agentSay(`Set a monthly ${f.values.category} budget of ${money(f.values.cents)}? Select “Confirm action” to save.`);return;}
  if(f.step==='confirm'){agentSay('Please confirm or cancel using the buttons.');return;}
 }
}
function beginGoal(){agentFlow={kind:'goal',step:'name',values:{}};agentSay('Absolutely! What is the name of your savings goal? For example: laptop, car, or emergency fund.');}
function beginRecurring(){agentFlow={kind:'recurring',step:'type',values:{}};agentSay('Let’s set a recurring reminder. Is this income or an expense?');}
function agentExtendedFlow(v){const f=agentFlow;if(f.kind==='goal'){if(f.step==='name'){if(!v.trim()){agentSay('What should we call the goal?');return;}f.values.name=v.slice(0,80);f.step='target';agentSay('What is your target amount in N$?');return;}if(f.step==='target'){const n=moneyInput(v);if(n===null){agentSay('Enter a positive target amount, such as 15000.');return;}f.values.target=n;f.step='saved';agentSay('How much have you already saved? Reply 0 if none.');return;}if(f.step==='saved'){const n=/^(0|0\.00)$/.test(v)?0:moneyInput(v);if(n===null){agentSay('Enter 0 or a valid positive amount.');return;}f.values.saved=n;f.step='date';agentSay('What is your target date? Enter YYYY-MM-DD or say skip.');return;}if(f.step==='date'){const date=/^(skip|no|none)$/i.test(v)?'':v;if(date&&!validDate(date)){agentSay('Use YYYY-MM-DD or skip.');return;}f.values.date=date;f.step='confirm';agentSay(`Create savings goal “${f.values.name}” with target ${money(f.values.target)}, already saved ${money(f.values.saved)}${date?' by '+date:''}? Confirm or cancel below.`);return;}}
if(f.kind==='recurring'){if(f.step==='type'){if(!/^(income|expense)$/i.test(v)){agentSay('Please choose income or expense.');return;}f.values.type=v.toLowerCase();f.step='description';agentSay('What is the recurring item called?');return;}if(f.step==='description'){if(!v.trim()){agentSay('Please enter a description.');return;}f.values.description=v.slice(0,100);f.step='amount';agentSay('What is the amount in N$?');return;}if(f.step==='amount'){const n=moneyInput(v);if(n===null){agentSay('Enter a positive amount.');return;}f.values.cents=n;f.step='category';agentSay('Choose a category: '+(f.values.type==='income'?incomeCategories:expenseCategories).join(', '));return;}if(f.step==='category'){const cat=(f.values.type==='income'?incomeCategories:expenseCategories).find(c=>c.toLowerCase()===v.toLowerCase());if(!cat){agentSay('Choose a listed category.');return;}f.values.category=cat;f.step='frequency';agentSay('Repeat weekly or monthly?');return;}if(f.step==='frequency'){if(!/^(weekly|monthly)$/i.test(v)){agentSay('Choose weekly or monthly.');return;}f.values.frequency=v.toLowerCase();f.step='nextDate';agentSay('When is it next due? Use YYYY-MM-DD or today.');return;}if(f.step==='nextDate'){const date=/^today$/i.test(v)?shiftDay(0):v;if(!validDate(date)){agentSay('Use a valid date YYYY-MM-DD.');return;}f.values.nextDate=date;f.values.date=date;f.values.notes='';f.step='confirm';agentSay(`Set ${f.values.frequency} ${f.values.type} “${f.values.description}” for ${money(f.values.cents)}, next due ${date}? Confirm below.`);return;}}}
function agentConfirm(){const f=agentFlow;if(!f||f.step!=='confirm')return;
 if(f.kind==='transaction'){const t={id:uid(),...f.values,sample:false};state.transactions.push(t);if(!save()){state.transactions.pop();agentSay('Could not store your transaction. Browser storage may be unavailable.');return;}agentFlow=null;agentSay(`Saved “${t.description}” for ${money(t.cents)}! Your charts and dashboard have updated.`);}
 else if(f.kind==='goal'){goals.push({id:uid(),...f.values});saveExtras();agentFlow=null;agentSay(`Your savings goal “${f.values.name}” is ready! I’ve added it to Savings Goals.`);}
 else if(f.kind==='recurring'){recurring.push({id:uid(),...f.values});saveExtras();agentFlow=null;agentSay(`Saved! Your ${f.values.frequency} reminder is now in Recurring and Calendar.`);}
 else if(f.kind==='budget'){const old=budgets[f.values.category];budgets[f.values.category]=f.values.cents;try{if(!saveBudgets())throw Error('Unable to save budget');agentFlow=null;agentSay(`${f.values.category} monthly budget set to ${money(f.values.cents)}. Your budget tracker is updated.`);}catch{if(old===undefined)delete budgets[f.values.category];else budgets[f.values.category]=old;agentSay('Budget could not be stored. Please check browser storage.');}}
}
function novaSend(text){const v=String(text||'').trim();if(v)agentHandle(v);}
function parseExpenseMessage(text){
 const message=text.trim().replace(/^nova\b[\s,.:!-]*/i,'');
 const match=message.match(/^(?:(?:i|we)\s+)?(?:spent|spend|paid|pay|bought|buy|purchased|purchase)\s+(?:n\$|nad|\$)?\s*(\d[\d,]*(?:\.\d{1,2})?)\s+(?:(?:on|for|at)\s+)?(.+)$/i);
 if(!match)return null;
 const raw=match[1].replace(/,/g,'');
 if(!/^\d+(?:\.\d{1,2})?$/.test(raw))return null;
 const amount=Number(raw),cents=Math.round(amount*100),description=match[2].trim().replace(/^[,.:;!?-]+|[,.:;!?-]+$/g,'');
 if(!description||description.length>100||!Number.isSafeInteger(cents)||cents<=0)return null;
 return {description,cents};
}
function agentHandle(text){const v=text.trim();if(!v)return;agentReply(v);if(agentFlow){agentHandleFlow(v);return;}const q=v.toLowerCase();
 const expense=parseExpenseMessage(v);if(expense){agentFlow={kind:'transaction',step:'confirm',values:{...expense,type:'expense',category:'Other Expenses',date:shiftDay(0),notes:''}};agentSay(`I understood: expense · ${expense.description} · ${money(expense.cents)} · Other Expenses · ${shiftDay(0)}. Confirm to save it to your FINOVA workspace, or cancel.`);return;}
 if(/^(?:nova[\s,.:!-]*)?(?:(?:i|we)\s+)?(?:spent|spend|paid|pay|bought|buy|purchased|purchase)\b/i.test(v)){agentSay('I can record that expense. Please include a positive amount and what you bought, for example “I spent 200 on alcohol”.');return;}
 if(/(add|create|record|log|new|enter).*\b(expense|spend|purchase|payment)\b|^add expense$/.test(q)){beginTransaction('expense');return;}
 if(/(add|create|record|log|new).*\b(income|salary|earning|revenue)\b|^add income$/.test(q)){beginTransaction('income');return;}
 if(/(savings goal|saving goal|save for|goal)/.test(q)){beginGoal();return;}
 if(/(recurring|subscription|repeat payment)/.test(q)){beginRecurring();return;}
 if(/(budget|spending limit)/.test(q)){beginBudget();return;}
 if(/(calendar|upcoming|due next)/.test(q)){navigate('/dashboard/calendar');agentSay('Opening your financial calendar and upcoming recurring reminders.');return;}
 if(/(switch profile|change profile|new profile)/.test(q)){agentSay('Opening local workspace selection.');chooseProfile();return;}
 if(/(this month|monthly spending)/.test(q)){const list=state.transactions.filter(t=>t.date.startsWith(formatYear(new Date())));agentSay(`This month, your recorded income is ${money(sum(list,'income'))}, expenses are ${money(sum(list,'expense'))}, and net is ${(sum(list,'income')-sum(list,'expense')<0?'-':'')+money(sum(list,'income')-sum(list,'expense'))}.`);return;}
 if(/(this month|monthly spending|spent this month)/.test(q)){const list=state.transactions.filter(t=>t.date.startsWith(formatYear(new Date())));agentSay(`This month you recorded income of ${money(sum(list,'income'))}, expenses of ${money(sum(list,'expense'))} and net cash flow of ${(sum(list,'income')-sum(list,'expense')<0?'-':'')+money(sum(list,'income')-sum(list,'expense'))}.`);return;}
 if(/(how much|summary|balance|total|insight|spent|spending|overview)/.test(q)){agentSummary();return;}
 if(/(export|download|csv)/.test(q)){exportCsv();agentSay('Your transaction CSV download has been started.');return;}
 if(/(search|find|transactions|history)/.test(q)){navigate('/dashboard/transactions');agentSay('Opened Transactions. You can search, sort and filter your records there.');return;}
 if(/(analytics|chart|graph|trend)/.test(q)){navigate('/dashboard/analytics');agentSay('Opened Analytics. The visualizations use your recorded transactions.');return;}
 if(/(settings|theme|appearance)/.test(q)){navigate('/dashboard/settings');agentSay('Opened Settings. You can adjust appearance and manage your local data.');return;}
 if(/(help|what can you|commands)/.test(q)){agentSay('I can:\n• Record a purchase: “I spent 200 on alcohol” (saved as Other Expenses after you confirm)\n• Add an expense or income step by step\n• Set a category budget\n• Create savings goals or recurring reminders\n• View your financial calendar\n• Show your spending summary\n• Open Transactions or Analytics\n• Export your CSV');return;}
 agentSay('I didn’t recognize that request. Try “add an expense”, “create a savings goal”, “recurring payment”, “set a budget”, “this month”, “calendar”, or “open analytics”.');}
function render(){const markup=page==='/'?siteHome():page==='/features'?siteFeatures():page==='/about'?siteAbout():page==='/dashboard'?overview():page==='/dashboard/transactions'?transactionsPage():page==='/dashboard/analytics'?analyticsPage():page==='/dashboard/budgets'?budgetsPage():page==='/dashboard/goals'?goalsPage():page==='/dashboard/recurring'?recurringPage():page==='/dashboard/calendar'?calendarPage():page==='/dashboard/insights'?insightsPage():settingsPage();app.innerHTML=(!activeProfile&&page.startsWith('/dashboard')?`<div class="app-shell"><main class="app-content"><p class="small-note">Choose a local workspace to continue.</p></main></div>${onboarding()}`:markup+(activeModal?modalHtml():'')+(paletteOpen?commandPalette():''))+(authPanel?authPanelHtml():'');window.finovaMotion?.enhance(app,page,activeProfile?.id);document.title=`${page==='/'?'Your money, in focus':page==='/features'?'Features':page==='/about'?'About':page.split('/').pop().replace(/^./,c=>c.toUpperCase())} — FINOVA`;}
function openModal(name,id=null){activeModal=name;editingId=id;render();document.querySelector('.modal input, .modal button')?.focus();}
function closeModal(){activeModal=null;editingId=null;render();}
function refreshPreservingSearch(){const el=document.activeElement;const id=el?.id;const position=(el?.selectionStart??0);render();if(id==='txSearch'){const n=document.getElementById(id);n?.focus();n?.setSelectionRange(position,position);}}
function exportProfile(){const payload={format:'FINOVA-profile-v3',exportedAt:new Date().toISOString(),name:prefs.displayName,transactions:state.transactions,budgets,goals,recurring,theme:prefs.theme};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='finova-'+prefs.displayName.toLowerCase().replace(/[^a-z0-9]+/g,'-')+'-backup.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Full workspace backup downloaded.');}
async function importProfile(file){if(!file)return;if(file.size>4_000_000){notify('Backup must be smaller than 4MB.');return;}try{const d=JSON.parse(await file.text());if(d.format!=='FINOVA-profile-v3'||!Array.isArray(d.transactions)||!Array.isArray(d.goals)||!Array.isArray(d.recurring)||!d.budgets||typeof d.budgets!=='object')throw Error('Not a FINOVA v3 backup.');if(d.transactions.length>10000||d.goals.length>1000||d.recurring.length>1000)throw Error('Backup contains too many records.');if(!d.transactions.every(validTransaction))throw Error('Invalid transaction data.');if(!d.goals.every(g=>typeof g.name==='string'&&g.name.length<=80&&Number.isSafeInteger(g.target)&&g.target>0&&Number.isSafeInteger(g.saved)&&g.saved>=0&&(!g.date||validDate(g.date))))throw Error('Invalid savings goals.');if(!d.recurring.every(r=>r&&typeof r.description==='string'&&validTransaction(r)&&validDate(r.nextDate)&&['monthly','weekly'].includes(r.frequency)))throw Error('Invalid recurring items.');if(!Object.entries(d.budgets).every(([c,n])=>expenseCategories.includes(c)&&Number.isSafeInteger(n)&&n>0))throw Error('Invalid budgets.');if(!confirm('Replace all financial records in '+prefs.displayName+'’s workspace with this backup? Export the current workspace first.'))return;state={transactions:d.transactions.map(t=>({...t,id:uid()})),demo:false};budgets=d.budgets;goals=d.goals.map(g=>({...g,id:uid()}));recurring=d.recurring.map(r=>({...r,id:uid()}));save();saveBudgets();saveExtras();render();notify('Workspace backup restored.');}catch(err){notify('Could not import backup: '+err.message);}}
function exportCsv(){const header=['Date','Description','Type','Category','Amount (NAD)','Notes'];const quote=s=>`"${String(s).replace(/"/g,'""')}"`;const rows=sortedTransactions().map(t=>[t.date,t.description,t.type,t.category,(t.cents/100).toFixed(2),t.notes].map(quote).join(','));const csv='\ufeff'+[header.map(quote).join(','),...rows].join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='finova-transactions.csv';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('CSV exported successfully.');}
function parseCsv(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const ch=text[i];if(ch==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(ch===','&&!quoted){row.push(cell);cell='';}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell='';}else cell+=ch;}if(quoted)throw Error('Unclosed CSV quote');row.push(cell);if(row.some(x=>x.trim()))rows.push(row);return rows;}
async function importCsv(file){if(!file)return;if(file.size>2_000_000){notify('CSV must be smaller than 2MB.');return;}try{const rows=parseCsv((await file.text()).replace(/^\uFEFF/,''));const header=rows.shift()?.map(x=>x.trim().toLowerCase());if(!header||!['date','description','type','category','amount (nad)'].every(x=>header.includes(x)))throw Error('Missing required columns. Export a FINOVA CSV to see the expected format.');if(rows.length>5000)throw Error('Maximum 5000 rows per import.');const added=[];for(const row of rows){const get=k=>String(row[header.indexOf(k)]||'').trim();const amount=get('amount (nad)');const type=get('type').toLowerCase();const cat=(type==='income'?incomeCategories:expenseCategories).find(x=>x.toLowerCase()===get('category').toLowerCase());const t={id:uid(),date:get('date'),description:get('description').slice(0,100),type,category:cat,cents:Math.round(Number(amount)*100),notes:get('notes').slice(0,300),sample:false};if(!/^\d+(\.\d{1,2})?$/.test(amount)||!validDate(t.date)||!validTransaction(t))throw Error('Invalid transaction on CSV row '+(added.length+2));added.push(t);}const previous=state.transactions;state.transactions=[...previous,...added];if(!save()){state.transactions=previous;return;}render();notify(`Imported ${added.length} transactions successfully.`);}catch(err){notify('Import failed: '+err.message);}}
function saveTransaction(form){const data=new FormData(form);const desc=String(data.get('description')||'').trim(),raw=String(data.get('amount')||'').trim(),type=String(data.get('type')),category=String(data.get('category')),date=String(data.get('date')),notes=String(data.get('notes')||'').trim();let invalid=false;document.querySelectorAll('[id^="error-"]').forEach(e=>e.textContent='');const error=(id,message)=>{const e=document.getElementById('error-'+id);if(e)e.textContent=message;invalid=true;};if(!desc)error('description','Enter a description.');if(!/^\d+(\.\d{1,2})?$/.test(raw)||!Number.isSafeInteger(Math.round(Number(raw)*100))||Number(raw)<=0)error('amount','Enter a positive amount with up to 2 decimals.');if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||Number.isNaN(Date.parse(date+'T12:00:00'))||new Date(date+'T12:00:00').toISOString().slice(0,10)!==date)error('date','Choose a valid date.');if(!['income','expense'].includes(type)||(type==='income'?incomeCategories:expenseCategories).includes(category)===false)error('description','Choose a valid transaction type and category.');if(invalid)return;const cents=Math.round(Number(raw)*100);const previous=editingId?state.transactions.find(t=>t.id===editingId):null;const tx={id:previous?.id||uid(),description:desc,cents,type,category,date,notes,sample:false};if(previous){state.transactions=state.transactions.map(t=>t.id===previous.id?tx:t);}else{state.transactions.push(tx);}save();closeModal();notify(previous?'Transaction updated.':'Transaction added.');}
// Event delegation keeps handlers working after route changes and re-renders.
document.addEventListener('click',event=>{const el=event.target.closest('button,[data-action]');if(!el)return;const action=el.dataset.action;if(el.id==='marketingMenu'){document.getElementById('siteLinks')?.classList.toggle('open');return;}if(el.id==='sidebarToggle'){document.getElementById('sidebar')?.classList.toggle('open');document.getElementById('mobileShade')?.classList.toggle('show');return;}if(el.id==='quickTheme'){prefs.theme=document.body.classList.contains('light')?'dark':'light';applyTheme();savePrefs();notify('Theme updated.');return;}if(el.id==='searchShortcut'){navigate('/dashboard/transactions');setTimeout(()=>document.getElementById('txSearch')?.focus(),20);return;}if(el.dataset.chart){graphMode=el.dataset.chart;render();return;}if(action==='profiles'){chooseProfile();return;}
if(action==='profile-switch'){switchProfile(el.dataset.id);return;}
if(action==='command-center'){paletteOpen=!paletteOpen;render();if(paletteOpen)document.getElementById('commandInput')?.focus();return;}
if(action==='command'){const cmd=el.dataset.command;paletteOpen=false;if(cmd.startsWith('/'))navigate(cmd);else if(cmd==='add')openModal('form');else if(cmd==='goal-add')openModal('goal-editor');else if(cmd==='recurring-add')openModal('recurring-editor');else if(cmd==='profiles'){chooseProfile();}else if(cmd==='agent-toggle'){agentOpen=true;render();}return;}
if(action==='drill-category'){navigate('/dashboard/transactions');setTimeout(()=>{categoryFilter=el.dataset.category;render();},30);return;}
if(action==='budget-edit'){openModal('budget-editor',el.dataset.category);return;}
if(action==='budget-remove'){if(confirm('Remove the '+el.dataset.category+' budget?')){delete budgets[el.dataset.category];saveBudgets();render();}return;}
if(action==='goal-add'){openModal('goal-editor');return;}
if(action==='goal-edit'){openModal('goal-editor',el.dataset.id);return;}
if(action==='goal-contribute'){openModal('goal-contribute',el.dataset.id);return;}
if(action==='goal-remove'){if(confirm('Delete this savings goal?')){goals=goals.filter(g=>g.id!==el.dataset.id);saveExtras();render();}return;}
if(action==='recurring-add'){openModal('recurring-editor');return;}
if(action==='recurring-edit'){openModal('recurring-editor',el.dataset.id);return;}
if(action==='recurring-remove'){if(confirm('Remove this recurring reminder?')){recurring=recurring.filter(r=>r.id!==el.dataset.id);saveExtras();render();}return;}
if(action==='recurring-record'){openModal('record-recurring',el.dataset.id);return;}
if(action==='confirm-record-recurring'){const r=recurring.find(x=>x.id===editingId);if(!r)return;const tx={id:uid(),description:r.description,cents:r.cents,category:r.category,type:r.type,date:r.nextDate,notes:'Recorded recurring transaction'};state.transactions.push(tx);if(!save()){state.transactions.pop();return;}r.nextDate=nextRecurringDate(r.nextDate,r.frequency);r.date=r.nextDate;saveExtras();closeModal();notify('Transaction recorded; reminder advanced.');return;}
if(action==='agent-goal'){agentOpen=true;beginGoal();return;}
if(action==='agent-recurring'){agentOpen=true;beginRecurring();return;}
if(action==='cal-prev'){calendarOffset--;render();return;}
if(action==='cal-next'){calendarOffset++;render();return;}
if(action==='cal-today'){calendarOffset=0;render();return;}
if(action==='calendar-day'){openModal('calendar-date',el.dataset.date);return;}
if(action==='agent-toggle'){agentOpen=!agentOpen;render();if(agentOpen){document.getElementById('novaChat')?.scrollTo(0,100000);document.getElementById('novaInput')?.focus();}return;}if(action==='agent-confirm'){agentConfirm();return;}if(action==='agent-cancel'){agentCancel();return;}if(action==='agent-budget'){agentOpen=true;beginBudget();return;}if(el.dataset.agentPrompt){novaSend(el.dataset.agentPrompt);return;}if(action==='export-profile'){exportProfile();return;}if(action==='import-profile'){document.getElementById('profileImport')?.click();return;}if(action==='import'){document.getElementById('csvImport')?.click();return;}if(action==='add'){openModal('form');return;}if(action==='edit'){openModal('form',el.dataset.id);return;}if(action==='delete'){openModal('delete',el.dataset.id);return;}if(action==='cancel'){closeModal();return;}if(action==='confirm-delete'){state.transactions=state.transactions.filter(t=>t.id!==editingId);save();closeModal();notify('Transaction deleted.');return;}if(action==='reset'){openModal('reset');return;}if(action==='confirm-reset'){state={transactions:[],demo:false};budgets={};goals=[];recurring=[];saveBudgets();saveExtras();save();closeModal();notify('This profile’s financial data was reset.');return;}if(action==='export'){exportCsv();return;}if(action==='save-name'){const value=document.getElementById('displayName')?.value.trim();if(!value){notify('Please enter a display name.');return;}prefs.displayName=value.slice(0,45);activeProfile.name=prefs.displayName;saveProfiles();savePrefs();render();notify('Profile saved.');}});
document.addEventListener('click',event=>{const authAction=event.target.closest('[data-action]')?.dataset.action;if(authAction==='account'){authPanel=true;render();return;}if(authAction==='auth-close'){authPanel=false;render();return;}if(authAction==='auth-logout'){cloudLogout();return;}if(event.target.id==='overlay')closeModal();if(event.target.id==='paletteShade'){paletteOpen=false;render();}if(event.target.id==='mobileShade'){document.getElementById('sidebar')?.classList.remove('open');event.target.classList.remove('show');}});
document.addEventListener('submit',event=>{if(event.target.id==='authForm'){event.preventDefault();accountSubmit(event.target,event.submitter?.value==='register'?'register':'login');return;}if(event.target.id==='transactionForm'){event.preventDefault();saveTransaction(event.target);}if(['budgetForm','goalForm','contributionForm','recurringForm'].includes(event.target.id)){event.preventDefault();handleManagementSubmit(event.target);}if(event.target.id==='createProfileForm'){event.preventDefault();createProfile(document.getElementById('newProfileName')?.value||'');}if(event.target.id==='novaForm'){event.preventDefault();novaSend(document.getElementById('novaInput')?.value||'');}});
document.addEventListener('input',event=>{if(event.target.id==='txSearch'){searchText=event.target.value;refreshPreservingSearch();}if(event.target.id==='commandInput'){const q=event.target.value.toLowerCase(),out=document.getElementById('commandResults');out.innerHTML=commandItems().filter(c=>c[1].toLowerCase().includes(q)).map(c=>`<button data-action="command" data-command="${esc(c[0])}"><span>${c[2]}</span>${esc(c[1])}<span>↗</span></button>`).join('')||'<div class="empty">No matching commands</div>';}});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='profileImport'){importProfile(el.files[0]);return;}if(el.id==='csvImport'){importCsv(el.files[0]);return;}if(el.id==='recType'){document.getElementById('recCategory').innerHTML=(el.value==='income'?incomeCategories:expenseCategories).map(c=>`<option>${c}</option>`).join('');}if(el.id==='txType'){const options=el.value==='income'?incomeCategories:expenseCategories;const category=document.getElementById('txCategory');category.innerHTML=options.map(c=>`<option value="${c}">${c}</option>`).join('');}if(el.id==='typeFilter'){typeFilter=el.value;render();}if(el.id==='categoryFilter'){categoryFilter=el.value;render();}if(el.id==='sortBy'){sortBy=el.value;render();}if(el.id==='period'){period=el.value;render();}if(el.id==='themeSelect'){prefs.theme=el.value;savePrefs();applyTheme();render();notify('Theme updated.');}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&activeModal)closeModal();if(event.key==='Escape'&&paletteOpen){paletteOpen=false;render();}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();paletteOpen=!paletteOpen;render();if(paletteOpen)document.getElementById('commandInput')?.focus();}});
matchMedia('(prefers-color-scheme: light)').addEventListener?.('change',()=>{if(prefs.theme==='system')applyTheme();});
window.addEventListener('hashchange',()=>{activeModal=null;editingId=null;readRoute();});
initProfiles();if(activeProfile)load();readRoute();cloudRestore();
